def parse_csv_line(line: str) -> list:
    fields = []
    i, n = 0, len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(line[i])
                i += 1
            fields.append(''.join(buf))
        else:
            j = line.find(',', i)
            if j == -1:
                fields.append(line[i:])
                i = n
            else:
                fields.append(line[i:j])
                i = j
        if i < n and line[i] == ',':
            i += 1
            if i == n:
                fields.append('')
                break
        else:
            break
    return fields
```

